import { useEffect, useRef, useState } from 'react';
import { Alert, Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, Stack, TextField, Tooltip, Typography } from '@mui/material';
import CloseRounded from '@mui/icons-material/CloseRounded';
import SaveOutlined from '@mui/icons-material/SaveOutlined';
import DownloadRounded from '@mui/icons-material/DownloadRounded';
import { ContentBlockBody } from './BlockCard';
import type { ContentBlock } from './protocol';
import { exportBlock, exportDocx, exportHtmlDocument, printDocument, suggestedFileName } from './exports';
import { inspectGeneratedFile, saveGeneratedFile } from '../engine/creator';
import { MarkdownBody } from '../components/MarkdownBody';
import { documentHeadings, documentWordCount } from './document';

export function BlockWorkbench({ block, onClose, onSave, onRewrite, projectFolder, history = [] }: { block: ContentBlock; onClose: () => void; onSave: (block: ContentBlock) => void; onRewrite?: (excerpt: string, document: ContentBlock) => void; projectFolder?: string; history?: { content: string; updatedAt: string }[] }) {
  const [draft, setDraft] = useState(block.content);
  const editorRef = useRef<HTMLTextAreaElement>(null);
  const [editing, setEditing] = useState(false);
  const [notice, setNotice] = useState('');
  const [filePath, setFilePath] = useState(suggestedFileName(block));
  const [review, setReview] = useState<{ exists: boolean; current: string } | null>(null);
  const [savingFile, setSavingFile] = useState(false);
  const [search, setSearch] = useState('');
  const [replacement, setReplacement] = useState('');
  const [advanced, setAdvanced] = useState(false);
  useEffect(() => { if (!editing) setDraft(block.content); }, [block.content, block.id]);
  useEffect(() => { setEditing(false); setNotice(''); setDraft(block.content); setFilePath(suggestedFileName(block)); setReview(null); }, [block.id]);
  const current = { ...block, content: draft };
  const save = () => { if (block.status === 'streaming') { setNotice('Wait until generation finishes to save this block.'); return; } onSave(current); setEditing(false); setNotice('Saved to the local Solarium asset library.'); };
  async function reviewFile() {
    if (!projectFolder) return;
    setSavingFile(true); setNotice('');
    try { setReview(await inspectGeneratedFile(projectFolder, filePath.trim())); }
    catch (error) { setNotice(`Cannot review project file: ${String(error)}`); }
    finally { setSavingFile(false); }
  }
  async function applyFile() {
    if (!projectFolder || !review) return;
    setSavingFile(true);
    try {
      await saveGeneratedFile(projectFolder, filePath.trim(), draft, review.exists ? review.current : null);
      setReview(null); setNotice('Saved to the selected project folder. Existing files receive a .solarium.bak backup.');
    } catch (error) { setNotice(`File was not saved: ${String(error)}`); }
    finally { setSavingFile(false); }
  }
  return <aside className="block-workbench" aria-label="Content block workspace">
    <header className="block-workbench-header"><Stack minWidth={0}><Typography fontSize={12} fontWeight={750} noWrap>{block.title}</Typography><Typography fontSize={10} color="text.secondary">{block.kind} · {block.status === 'streaming' ? 'Streaming' : 'Editable asset'}</Typography></Stack><Box flex={1}/><Tooltip title="Close block workspace"><IconButton size="small" aria-label="Close block workspace" onClick={onClose}><CloseRounded fontSize="small"/></IconButton></Tooltip></header>
    <Stack direction="row" gap={.5} px={1} py={.6} flexWrap="wrap">
      <Button size="small" variant={editing ? 'contained' : 'text'} onClick={() => setEditing((v) => !v)} disabled={block.status === 'streaming'}>{editing ? 'Preview' : 'Edit'}</Button>
      <Button size="small" onClick={() => setAdvanced((v) => !v)}>Find / history</Button>
      {block.kind === 'writing' && <Typography fontSize={10} color="text.secondary">{documentWordCount(draft)} words · {draft.length} characters</Typography>}
      {block.kind === 'writing' && onRewrite && <Button size="small" onClick={() => { const field = editorRef.current; if (!field) { setEditing(true); return; } const excerpt = field.value.slice(field.selectionStart, field.selectionEnd).trim(); if (!excerpt) { setNotice('Select the passage you want the Spark to rewrite, then press Ask Spark.'); return; } onRewrite(excerpt, current); }}>Ask Spark to rewrite selection</Button>}
      <Button size="small" startIcon={<SaveOutlined fontSize="small"/>} onClick={save} disabled={block.status === 'streaming'}>Save asset</Button>
      <Button size="small" startIcon={<DownloadRounded fontSize="small"/>} onClick={() => exportBlock(current)}>Export</Button>
      {projectFolder && ['code', 'writing', 'table', 'preview'].includes(block.kind) && <Button size="small" disabled={block.status === 'streaming'} onClick={() => void reviewFile()}>Review to project</Button>}
      {block.kind === 'writing' && <><Button size="small" onClick={() => exportDocx(draft, block.title + '.docx')}>DOCX</Button><Button size="small" onClick={() => exportHtmlDocument(draft, block.title)}>HTML</Button><Button size="small" onClick={() => printDocument(draft, block.title)}>Print / PDF</Button></>}
    </Stack>
    {advanced && <Box px={1} py={.6} className="block-advanced-controls"><Stack direction="row" gap={.7} alignItems="center"><TextField size="small" label="Find" value={search} onChange={(e) => setSearch(e.target.value)}/><TextField size="small" label="Replace" value={replacement} onChange={(e) => setReplacement(e.target.value)}/><Button size="small" disabled={!search || block.status === 'streaming'} onClick={() => { setDraft((text) => text.split(search).join(replacement)); setEditing(true); }}>Replace all</Button></Stack>
      {history.length > 0 && <Box mt={1}><Typography fontSize={10} fontWeight={700}>Previous saved versions</Typography><Stack gap={.4}>{history.slice().reverse().map((item, i) => <Button key={i} size="small" sx={{ justifyContent: 'start' }} onClick={() => { setDraft(item.content); setEditing(true); }}>{new Date(item.updatedAt).toLocaleString()} · Restore in editor</Button>)}</Stack></Box>}
    </Box>}
    {projectFolder && ['code', 'writing', 'table', 'preview'].includes(block.kind) && <TextField size="small" label="Project-relative filename" value={filePath} onChange={(e) => setFilePath(e.target.value)} sx={{ mx: 1, my: .5 }} />}
    {notice && <Alert sx={{ m: 1 }} severity="info" onClose={() => setNotice('')}>{notice}</Alert>}
    <div className="block-workbench-content">{editing && block.kind === 'writing' ? <div className="writing-editor-layout">
      <section className="writing-document-outline"><Typography fontWeight={700} fontSize={11}>Outline</Typography>{documentHeadings(draft).map((heading) => <button key={`${heading.line}-${heading.label}`} style={{ paddingLeft: 7 + heading.level * 9 }} onClick={() => { const field = editorRef.current; if (!field) return; const pos = field.value.split('\n').slice(0, heading.line - 1).reduce((total, line) => total + line.length + 1, 0); field.focus(); field.setSelectionRange(pos, pos); }}>{heading.label}</button>)}</section>
      <textarea ref={editorRef} autoFocus className="writing-markdown-source" aria-label="Editable document markdown" spellCheck value={draft} onChange={(event) => setDraft(event.target.value)} />
      <div className="writing-live-render"><MarkdownBody text={draft}/></div>
    </div> : editing ? <textarea className="block-source-editor" autoFocus spellCheck={false} aria-label="Editable source code" value={draft} onChange={(event) => setDraft(event.target.value)} /> : <ContentBlockBody block={current} />}</div>
    <Typography fontSize={10} color="text.secondary" px={1.5} py={1}>Edits are stored as an independent asset; the original assistant message is never overwritten.</Typography>
    <Dialog open={Boolean(review)} onClose={() => setReview(null)} fullWidth maxWidth="lg"><DialogTitle>Review file changes — {filePath}</DialogTitle><DialogContent>
      <Typography fontSize={11} color="text.secondary" mb={1}>{review?.exists ? 'Compare the existing file against the proposed replacement. An automatic backup is created before overwriting.' : 'This is a new file. Solarium will create it only after you approve.'}</Typography>
      <div className="block-file-diff"><div><Typography fontSize={11} mb={1} fontWeight={700}>Current file</Typography><pre>{review?.exists ? review.current : '(new file)'}</pre></div><div><Typography fontSize={11} mb={1} fontWeight={700}>Proposed file</Typography><pre>{draft}</pre></div></div>
    </DialogContent><DialogActions><Button onClick={() => setReview(null)}>Cancel</Button><Button variant="contained" disabled={savingFile} onClick={() => void applyFile()}>Apply reviewed change</Button></DialogActions></Dialog>
  </aside>;
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { Alert, Box, Button, Stack, Typography } from '@mui/material';
import { createPreviewDocument, describePreviewSource } from './preview-source';

export function LivePreview({ content, finished = true }: { content: string; finished?: boolean }) {
  const frame = useRef<HTMLIFrameElement>(null);
  const nonce = useRef(`preview-${Math.random().toString(36).slice(2)}`);
  const [viewport, setViewport] = useState<'desktop' | 'tablet' | 'mobile'>('desktop');
  const [runtime, setRuntime] = useState<{ kind: 'loading' | 'ready' | 'empty' | 'error'; text: string }>({ kind: 'loading', text: 'Preparing preview…' });
  const [showSource, setShowSource] = useState(false);
  const [refresh, setRefresh] = useState(0);
  const [stableContent, setStableContent] = useState(content);
  useEffect(() => {
    if (finished) { setStableContent(content); return; }
    const timer = window.setTimeout(() => setStableContent(content), 350);
    return () => window.clearTimeout(timer);
  }, [content, finished]);
  const source = useMemo(() => describePreviewSource(stableContent, finished), [stableContent, finished]);
  const srcDoc = useMemo(() => source.html ? createPreviewDocument(source, nonce.current) : '', [source, refresh]);
  useEffect(() => {
    setRuntime({ kind: 'loading', text: source.description });
  }, [srcDoc, source.kind, source.description]);
  useEffect(() => {
    function onMessage(event: MessageEvent) {
      if (event.source !== frame.current?.contentWindow || event.origin !== 'null') return;
      const data: unknown = event.data;
      if (!data || typeof data !== 'object') return;
      const record = data as { solariumPreview?: boolean; id?: string; type?: string; message?: string };
      if (!record.solariumPreview || record.id !== nonce.current) return;
      if (record.type === 'error') setRuntime({ kind: 'error', text: (record.message || 'Preview runtime error').slice(0, 600) });
      if (record.type === 'empty') setRuntime((state) => state.kind === 'error' ? state : { kind: 'empty', text: record.message || 'The preview is empty.' });
      if (record.type === 'ready') setRuntime((state) => state.kind === 'error' ? state : { kind: 'ready', text: 'Preview loaded' });
    }
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  }, []);
  const viewWidth = viewport === 'mobile' ? 390 : viewport === 'tablet' ? 740 : undefined;
  return <div className="live-preview">
    <Stack direction="row" alignItems="center" gap={.5} className="preview-toolbar" flexWrap="wrap">
      <Typography fontSize={10} sx={{ mr: 'auto' }}>{source.description}</Typography>
      {(['desktop', 'tablet', 'mobile'] as const).map((size) => <Button key={size} size="small" onClick={() => setViewport(size)} variant={viewport === size ? 'contained' : 'text'}>{size}</Button>)}
      <Button size="small" onClick={() => setRefresh((v) => v + 1)} disabled={!srcDoc}>Refresh</Button>
      <Button size="small" onClick={() => setShowSource((v) => !v)}>{showSource ? 'Hide source' : 'Source'}</Button>
    </Stack>
    {source.kind === 'unsupported' || source.kind === 'incomplete' ? <Alert severity={source.kind === 'unsupported' ? 'warning' : 'info'} sx={{ m: 1 }}>{source.description}</Alert> : <>
      {runtime.kind === 'error' || runtime.kind === 'empty' ? <Alert severity={runtime.kind === 'error' ? 'error' : 'warning'} sx={{ m: 1 }}>{runtime.text}</Alert> : <Typography sx={{ px: 1, py: .45 }} color="text.secondary" fontSize={10}>{runtime.kind === 'ready' ? '● Preview ready · offline sandbox' : 'Preparing isolated preview…'}</Typography>}
      <Box className="preview-viewport"><iframe key={`${refresh}-${source.kind}`} ref={frame} onLoad={() => setRuntime((state) => state.kind === 'error' || state.kind === 'empty' ? state : { kind: 'ready', text: 'Preview loaded' })} title="Isolated live code preview" className="block-preview-frame" sandbox="allow-scripts" referrerPolicy="no-referrer" srcDoc={srcDoc} style={{ maxWidth: viewWidth, width: '100%' }} /></Box>
    </>}
    {showSource && <pre className="preview-source">{content}</pre>}
  </div>;
}

import { useEffect, useMemo, useState } from 'react';
import { Alert, Box, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, MenuItem, Stack, Switch, Tab, Tabs, TextField, Typography } from '@mui/material';
import { useLibraryContext } from '../foundation/ui-context';
import { StoryRepository, claimKinds, claimSections, type CharacterClaim, type ClaimData, type ClaimSection, type StoryCharacter, type StoryEvent, type StoryRelation, type StoryWorld } from '../stories/repository';
import { SourceRepository, type SavedSource } from '../sources/repository';
import { useSolarium } from '../state/useSolarium';
import { downloadBytes } from '../blocks/exports';
import { exportFoundation } from '../foundation/store';
export function StoryBible(){
  const {access,scope,session,project}=useLibraryContext();const repo=useMemo(()=>new StoryRepository(access),[access]);
  const [worlds,setWorlds]=useState<StoryWorld[]>([]),[worldId,setWorldId]=useState(session?.storyId??''),[world,setWorld]=useState<StoryWorld|null>(null),[cast,setCast]=useState<StoryCharacter[]>([]),[sources,setSources]=useState<SavedSource[]>([]),[events,setEvents]=useState<StoryEvent[]>([]),[relations,setRelations]=useState<StoryRelation[]>([]),[error,setError]=useState(''),[newWorld,setNewWorld]=useState(false),[name,setName]=useState(''),[newCharacter,setNewCharacter]=useState(false),[selected,setSelected]=useState<StoryCharacter|null>(null),[eventForm,setEventForm]=useState(false),[eventTitle,setEventTitle]=useState(''),[eventSummary,setEventSummary]=useState(''),[eventOrder,setEventOrder]=useState('1'),[eventCast,setEventCast]=useState<string[]>([]),[relationForm,setRelationForm]=useState(false),[from,setFrom]=useState(''),[to,setTo]=useState(''),[nature,setNature]=useState('');
  const load=async(id=worldId)=>{const list=await repo.list();setWorlds(list);if(id&&list.some(w=>w.id===id)){const w=list.find(w=>w.id===id)!;setWorld(w);const [c,s,e,r]=await Promise.all([repo.characters(id),new SourceRepository(access).list(),repo.events(id),repo.relations(id)]);setCast(c);setSources(s);setEvents(e);setRelations(r);}else{setWorld(null);setCast([]);}};
  useEffect(()=>{let disposed=false;void repo.list().then(list=>{if(!disposed)setWorlds(list);}).catch(e=>setError(String(e)));return()=>{disposed=true;};},[repo]);
  useEffect(()=>{void load().catch(e=>setError(String(e)));},[worldId,repo]);
  async function perform(fn:()=>Promise<unknown>){try{await fn();await load();setError('');}catch(e){setError(String(e));}}
  function choose(id:string){setWorldId(id);if(session)useSolarium.getState().updateSession(session.id,{storyId:id||null});}
  function ask(prompt:string){if(!world)return;const state=useSolarium.getState();let id=session?.id;if(!id)id=state.createSession(undefined,project?.id??null);state.updateSession(id,{storyId:world.id});useSolarium.setState({pendingComposer:prompt,view:'chat'});}
  return <Box className="view-scroll page-padding"><Stack gap={1.5}><Typography variant="h5" fontWeight={750}>Story Bible</Typography><Typography color="text.secondary" fontSize={12}>Story characters and continuity stay separate from your Spark. Canon, interpretations and AU choices retain their provenance.</Typography>{error&&<Alert severity="error" onClose={()=>setError('')}>{error}</Alert>}
    <Stack direction="row" gap={1} flexWrap="wrap"><TextField select label="Story World" value={worldId} onChange={e=>choose(e.target.value)} sx={{minWidth:240}}><MenuItem value="">Choose a world</MenuItem>{worlds.map(w=><MenuItem key={w.id} value={w.id}>{w.title}</MenuItem>)}</TextField><Button variant="contained" onClick={()=>{setName('');setNewWorld(true);}}>New Story World</Button>{world&&<><Button onClick={()=>void perform(async()=>{const title=prompt('Name the alternate branch',world.title+' — alternate route');if(!title)return;const divergence=prompt('What changes in this branch?',world.data.divergenceNote);if(divergence===null)return;const child=await repo.branch(world.id,title,divergence);choose(child.id);})}>Create alternate branch</Button><Button onClick={()=>void perform(async()=>{const archive=await exportFoundation(repo.store,[world.scope]);const related=archive.records.filter(e=>e.record.id===world.id||e.record.storyId===world.id||world.data.sourceIds.includes(e.record.id));downloadBytes(JSON.stringify({...archive,records:related},null,2),'application/json','solarium-story-world.json');})}>Export Story World</Button></>}</Stack>
    {world&&<><details className="glass foundation-card"><summary>World settings · {world.title}</summary><Stack gap={1.5} mt={2}><TextField label="World title" value={world.title} onChange={e=>setWorld({...world,title:e.target.value})}/><Stack direction="row" gap={1} flexWrap="wrap"><TextField select label="Origin" value={world.data.originKind} onChange={e=>setWorld({...world,data:{...world.data,originKind:e.target.value as typeof world.data.originKind}})}>{['original','fanfiction','mixed'].map(k=><MenuItem key={k} value={k}>{k}</MenuItem>)}</TextField><TextField label="Franchise" value={world.data.franchiseName} onChange={e=>setWorld({...world,data:{...world.data,franchiseName:e.target.value}})}/><TextField label="Canon continuity (web novel / light novel / anime)" value={world.data.canonAnchor} onChange={e=>setWorld({...world,data:{...world.data,canonAnchor:e.target.value}})} sx={{flex:1}}/></Stack><TextField label="Branch / continuity point" value={world.data.continuityPoint} onChange={e=>setWorld({...world,data:{...world.data,continuityPoint:e.target.value}})}/><Stack direction="row" gap={1}><TextField type="number" label="Spoiler boundary: arc" value={world.data.spoilerArc??''} onChange={e=>setWorld({...world,data:{...world.data,spoilerArc:e.target.value?Number(e.target.value):undefined}})}/><TextField type="number" label="Chapter" value={world.data.spoilerChapter??''} onChange={e=>setWorld({...world,data:{...world.data,spoilerChapter:e.target.value?Number(e.target.value):undefined}})}/></Stack><TextField multiline minRows={2} label="Intentional AU divergences" value={world.data.divergenceNote} onChange={e=>setWorld({...world,data:{...world.data,divergenceNote:e.target.value}})}/><Stack direction="row" gap={1}>{(['pov','tense','tone'] as const).map(field=><TextField key={field} label={field.toUpperCase()} value={world.data.narration[field]} onChange={e=>setWorld({...world,data:{...world.data,narration:{...world.data.narration,[field]:e.target.value}}})}/>)}</Stack><Button variant="contained" onClick={()=>void perform(()=>repo.update(world,world.data,world.title))}>Save world settings</Button></Stack></details>
      <Stack direction="row" gap={1} alignItems="center" flexWrap="wrap"><Typography variant="h6" flex={1}>Characters · {cast.length}</Typography><Button variant="contained" onClick={()=>{setName('');setNewCharacter(true);}}>New character</Button><Button onClick={()=>ask(`Research the relevant cast for ${world.data.franchiseName} at ${world.data.continuityPoint}. Build separate character dossiers section by section: Identity, Appearance, Personality & Voice, History, Abilities, Relationships, Knowledge State and Situation. Use saved evidence, respect the spoiler boundary, leave unsupported fields unknown, and preserve locked AU facts.`)}>Build grounded profiles with Spark</Button><Button onClick={()=>ask(`Research the exact scene at ${world.data.continuityPoint} in ${world.data.franchiseName} ${world.data.canonAnchor}. Verify actual page content and distinguish similar incidents.`)}>Research canon scene</Button></Stack>
      <Box className="foundation-grid">{cast.map(c=><Box className="glass foundation-card character-card" key={c.id}>{c.data.portrait?<img src={c.data.portrait} alt={c.title}/>:<div className="character-monogram" aria-hidden="true">{c.title.slice(0,2)}</div>}<Button sx={{fontWeight:750}} onClick={()=>setSelected(c)}>{c.title}</Button><Typography fontSize={11} color="text.secondary">{c.data.role||'Role not defined'} · {c.data.characterKind}</Typography><Typography fontSize={10}>{c.data.aliases.join(' · ')}</Typography><Button size="small" onClick={()=>ask(`Research ${c.title} for our active Story World. Populate Identity, Appearance, Personality & Voice, History, Abilities, Relationships and Situation in order using concise sourced claims. Keep unsupported fields unknown and do not overwrite locked facts.`)}>Research dossier</Button></Box>)}</Box>
      {!cast.length&&<Typography color="text.secondary">No character cards yet. Add original characters offline, or research canon characters with your Spark.</Typography>}
      <Stack direction="row" gap={1}><Button onClick={()=>{setEventTitle('');setEventSummary('');setEventForm(true);}}>Add timeline event / scene beat</Button><Button onClick={()=>setRelationForm(true)} disabled={cast.length<2}>Add relationship</Button></Stack>
      <Box className="library-layout"><Box className="glass foundation-card"><Typography fontWeight={700}>Timeline and outline</Typography>{events.sort((a,b)=>a.data.order-b.data.order).map(e=><Box key={e.id} my={1}><Typography fontSize={12}>{e.data.order}. {e.title} <Chip size="small" label={e.data.kind}/></Typography><Typography fontSize={11} color="text.secondary">{e.data.summary}</Typography><Typography fontSize={10}>Known by: {Object.entries(e.data.knowledge).map(([id,state])=>`${cast.find(c=>c.id===id)?.title??id}: ${state}`).join(', ')||'Not established'}</Typography></Box>)}</Box><Box className="glass foundation-card"><Typography fontWeight={700}>Relationships at this point</Typography>{relations.map(r=><Typography fontSize={12} key={r.id} my={1}>{cast.find(c=>c.id===r.data.from)?.title} → {cast.find(c=>c.id===r.data.to)?.title}: {r.data.nature}</Typography>)}</Box></Box>
      <Button onClick={()=>ask(`Write the next chapter of "${world.title}" using our selected continuity, AU divergence and relevant character voice guides. Open one solarium-writing document and preserve character knowledge at the spoiler boundary.`)}>Start chapter with Spark</Button>
    </>}
    <Dialog open={newWorld||newCharacter} onClose={()=>{setNewWorld(false);setNewCharacter(false);}} fullWidth maxWidth="sm"><DialogTitle>{newWorld?'Create Story World':'Create character dossier'}</DialogTitle><DialogContent><TextField fullWidth autoFocus label="Name" sx={{mt:1}} value={name} onChange={e=>setName(e.target.value)}/><Typography fontSize={11} mt={2}>{newWorld?'You can configure continuity, narration, spoilers and AU choices after creation.':'Start with a separate blank dossier. Original facts and source evidence can be added per field.'}</Typography></DialogContent><DialogActions><Button onClick={()=>{setNewWorld(false);setNewCharacter(false);}}>Cancel</Button><Button disabled={!name.trim()} variant="contained" onClick={()=>void perform(async()=>{if(newWorld){const w=await repo.create(name,scope);choose(w.id);}else if(world)await repo.character(world.id,name,[],world.data.originKind==='original'?'original':'canon');setNewWorld(false);setNewCharacter(false);})}>Create</Button></DialogActions></Dialog>
    <Dialog open={eventForm} onClose={()=>setEventForm(false)} fullWidth maxWidth="sm"><DialogTitle>Timeline event / scene beat</DialogTitle><DialogContent><Stack gap={2} pt={1}><TextField label="Title" value={eventTitle} onChange={e=>setEventTitle(e.target.value)}/><TextField label="Summary / outline" multiline minRows={3} value={eventSummary} onChange={e=>setEventSummary(e.target.value)}/><TextField type="number" label="Order" value={eventOrder} onChange={e=>setEventOrder(e.target.value)}/><TextField select label="Who knows this event?" SelectProps={{multiple:true}} value={eventCast} onChange={e=>setEventCast(typeof e.target.value==='string'?e.target.value.split(','):e.target.value)}>{cast.map(c=><MenuItem key={c.id} value={c.id}>{c.title}</MenuItem>)}</TextField></Stack></DialogContent><DialogActions><Button onClick={()=>setEventForm(false)}>Cancel</Button><Button disabled={!eventTitle.trim()} onClick={()=>world&&void perform(async()=>{await repo.event(world.id,eventTitle,{order:Number(eventOrder)||0,arc:world.data.spoilerArc,chapter:world.data.spoilerChapter,characters:eventCast,kind:'user_defined',sourceLinks:[],knowledge:Object.fromEntries(eventCast.map(id=>[id,'knows' as const])),summary:eventSummary});setEventForm(false);})}>Save event</Button></DialogActions></Dialog>
    <Dialog open={relationForm} onClose={()=>setRelationForm(false)} fullWidth maxWidth="sm"><DialogTitle>Directed relationship</DialogTitle><DialogContent><Stack gap={2} pt={1}>{[['From',from,setFrom],['To',to,setTo]].map(([label,value,setter])=><TextField key={label as string} select label={label as string} value={value as string} onChange={e=>(setter as (v:string)=>void)(e.target.value)}>{cast.map(c=><MenuItem key={c.id} value={c.id}>{c.title}</MenuItem>)}</TextField>)}<TextField label="Relationship at this story point" multiline minRows={3} value={nature} onChange={e=>setNature(e.target.value)}/></Stack></DialogContent><DialogActions><Button onClick={()=>setRelationForm(false)}>Cancel</Button><Button disabled={!from||!to||!nature.trim()} onClick={()=>world&&void perform(async()=>{await repo.relation(world.id,'Relationship',{from,to,nature,effectiveArc:world.data.spoilerArc,effectiveChapter:world.data.spoilerChapter,sourceLinks:[]});setRelationForm(false);})}>Save relationship</Button></DialogActions></Dialog>
    {selected&&world&&<CharacterDossier character={selected} story={world} repo={repo} sources={sources} onClose={()=>{setSelected(null);void load();}}/>}
  </Stack></Box>;
}
function CharacterDossier({character,story,repo,sources,onClose}:{character:StoryCharacter;story:StoryWorld;repo:StoryRepository;sources:SavedSource[];onClose:()=>void}){
  const [card,setCard]=useState(character),[claims,setClaims]=useState<CharacterClaim[]>([]),[section,setSection]=useState<ClaimSection>('Identity'),[field,setField]=useState(''),[value,setValue]=useState(''),[kind,setKind]=useState<ClaimData['kind']>('unknown'),[sourceId,setSourceId]=useState(''),[locator,setLocator]=useState(''),[quote,setQuote]=useState(''),[locked,setLocked]=useState(false),[error,setError]=useState(''),[versions,setVersions]=useState<import('../foundation/types').StoredRecord[]>([]);
  const refresh=()=>repo.claims(card.id,story.id).then(setClaims);
  useEffect(()=>{void refresh();void repo.store.list<{characterId?:string}>({collection:'character_claim_revision',scopes:repo.scopes(),storyId:story.id}).then(rows=>setVersions(rows.filter(r=>r.data.characterId===card.id)));},[card.id,story.id,repo]);
  function edit(c:CharacterClaim){setSection(c.data.section);setField(c.data.field);setValue(c.data.value);setKind(c.data.kind);setLocked(c.data.locked);setSourceId(c.data.sourceLinks[0]?.sourceId??'');setLocator(c.data.sourceLinks[0]?.locator??'');setQuote(c.data.sourceLinks[0]?.quote??'');}
  async function save(){try{await repo.saveClaims(card,[{characterId:card.id,section,field,value,kind,locked,reviewed:true,effectiveArc:story.data.spoilerArc,effectiveChapter:story.data.spoilerChapter,sourceLinks:sourceId?[{sourceId,locator,synopsis:value.slice(0,500),quote,continuity:story.data.canonAnchor,confidence:'medium'}]:[]}],true);await refresh();setField('');setValue('');setError('');}catch(e){setError(String(e));}}
  return <Dialog open onClose={onClose} fullWidth maxWidth="lg"><DialogTitle>{card.title} · {story.title}</DialogTitle><DialogContent>{error&&<Alert severity="error" onClose={()=>setError('')}>{error}</Alert>}
    <Stack direction="row" gap={1} flexWrap="wrap" my={1}><TextField label="Character name" value={card.title} onChange={e=>setCard({...card,title:e.target.value})}/><TextField label="Aliases, separated by commas" value={card.data.aliases.join(', ')} onChange={e=>setCard({...card,data:{...card.data,aliases:e.target.value.split(',').map(v=>v.trim()).filter(Boolean)}})}/><TextField label="Story role" value={card.data.role} onChange={e=>setCard({...card,data:{...card.data,role:e.target.value}})}/><Button onClick={()=>void repo.editCharacter(card,card.title,card.data).then(setCard).catch(e=>setError(String(e)))}>Save identity</Button><Button component="label">Local portrait<input hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1_500_000){setError('Portrait limit is 1.5 MB.');return;}const reader=new FileReader();reader.onload=()=>void repo.editCharacter(card,card.title,{...card.data,portrait:String(reader.result)}).then(setCard).catch(e=>setError(String(e)));reader.readAsDataURL(file);}}/></Button></Stack>
    <Typography fontSize={11} color="text.secondary">Coverage: {claims.filter(c=>['canon_confirmed','source_supported'].includes(c.data.kind)).length} grounded · {claims.filter(c=>c.data.kind==='user_defined'||c.data.kind==='au_override').length} user/AU · {claimSections.filter(s=>!claims.some(c=>c.data.section===s)).length} unknown sections · {claims.filter(c=>c.data.kind==='disputed').length} disputed · {versions.length} prior field versions</Typography>
    <Tabs value={section} onChange={(_,v)=>setSection(v as ClaimSection)} variant="scrollable" scrollButtons="auto">{claimSections.map(s=><Tab key={s} value={s} label={s}/>)}</Tabs>
    <Stack gap={1} my={2}>{claims.filter(c=>c.data.section===section).map(c=><Box className="glass foundation-card" key={c.id}><Stack direction="row" alignItems="center" gap={1}><Typography fontSize={12} fontWeight={700} flex={1}>{c.data.field}</Typography><Chip size="small" label={`${c.data.kind.replaceAll('_',' ')}${c.data.locked?' · locked':''}`}/><Button size="small" onClick={()=>edit(c)}>Edit / Review</Button></Stack><Typography fontSize={12} whiteSpace="pre-wrap">{c.data.value||'Unknown'}</Typography>{c.data.sourceLinks.map((l,i)=><Typography key={i} fontSize={10} color="text.secondary">{sources.find(s=>s.id===l.sourceId)?.title??'Source unavailable'} · {l.locator} · {l.confidence}</Typography>)}</Box>)}{!claims.some(c=>c.data.section===section)&&<Typography color="text.secondary">Unknown — no supported or user-authored fields in this section yet.</Typography>}</Stack>
    <Stack gap={1.5} className="glass foundation-card"><Typography fontSize={13} fontWeight={700}>Add / update a {section} field</Typography><Stack direction="row" gap={1}><TextField label="Field" value={field} onChange={e=>setField(e.target.value)} sx={{flex:1}}/><TextField select label="Provenance" value={kind} onChange={e=>setKind(e.target.value as ClaimData['kind'])} sx={{minWidth:180}}>{claimKinds.map(k=><MenuItem key={k} value={k}>{k.replaceAll('_',' ')}</MenuItem>)}</TextField></Stack><TextField label="Concise claim / original character fact" multiline minRows={3} value={value} onChange={e=>setValue(e.target.value)}/><Stack direction="row" gap={1}><TextField select label="Evidence source" value={sourceId} onChange={e=>setSourceId(e.target.value)} sx={{flex:1}}><MenuItem value="">No source — unknown / original / user choice</MenuItem>{sources.map(s=><MenuItem key={s.id} value={s.id}>{s.title}</MenuItem>)}</TextField><TextField label="Chapter / passage locator" value={locator} onChange={e=>setLocator(e.target.value)}/></Stack><TextField label="Brief supporting excerpt (optional for manual review)" value={quote} onChange={e=>setQuote(e.target.value)} inputProps={{maxLength:500}}/><FormControlLabel control={<Switch checked={locked} onChange={(_,v)=>setLocked(v)}/>} label="Lock against automated research updates"/><Button variant="contained" disabled={!field.trim()} onClick={()=>void save()}>Save field revision</Button></Stack>
  </DialogContent><DialogActions><Button onClick={onClose}>Close dossier</Button></DialogActions></Dialog>;
}
